SELECT 'gw1000' AS archive, 24 AS gap_count, COUNT(DISTINCT gap_id) AS gaps_with_any_rows, 24-COUNT(DISTINCT gap_id) AS gaps_without_rows, COUNT(*) AS source_rows, COUNT(DISTINCT CASE WHEN `outTemp` IS NOT NULL THEN gap_id END) AS gaps_with_outTemp, SUM(`outTemp` IS NOT NULL) AS values_outTemp, COUNT(DISTINCT CASE WHEN `outHumidity` IS NOT NULL THEN gap_id END) AS gaps_with_outHumidity, SUM(`outHumidity` IS NOT NULL) AS values_outHumidity, COUNT(DISTINCT CASE WHEN `rain` IS NOT NULL THEN gap_id END) AS gaps_with_rain, SUM(`rain` IS NOT NULL) AS values_rain, COUNT(DISTINCT CASE WHEN `rainRate` IS NOT NULL THEN gap_id END) AS gaps_with_rainRate, SUM(`rainRate` IS NOT NULL) AS values_rainRate, COUNT(DISTINCT CASE WHEN `windSpeed` IS NOT NULL THEN gap_id END) AS gaps_with_windSpeed, SUM(`windSpeed` IS NOT NULL) AS values_windSpeed, COUNT(DISTINCT CASE WHEN `windGust` IS NOT NULL THEN gap_id END) AS gaps_with_windGust, SUM(`windGust` IS NOT NULL) AS values_windGust, COUNT(DISTINCT CASE WHEN `barometer` IS NOT NULL THEN gap_id END) AS gaps_with_barometer, SUM(`barometer` IS NOT NULL) AS values_barometer FROM (SELECT CASE WHEN `dateTime`>1357466400 AND `dateTime`<1357472100 THEN 1 WHEN `dateTime`>1359457200 AND `dateTime`<1359529500 THEN 2 WHEN `dateTime`>1360676100 AND `dateTime`<1360680300 THEN 3 WHEN `dateTime`>1360921500 AND `dateTime`<1360927200 THEN 4 WHEN `dateTime`>1362166800 AND `dateTime`<1362171600 THEN 5 WHEN `dateTime`>1362580800 AND `dateTime`<1362644700 THEN 6 WHEN `dateTime`>1363401300 AND `dateTime`<1363407300 THEN 7 WHEN `dateTime`>1363409100 AND `dateTime`<1363413300 THEN 8 WHEN `dateTime`>1363415100 AND `dateTime`<1363419300 THEN 9 WHEN `dateTime`>1363421100 AND `dateTime`<1363425300 THEN 10 WHEN `dateTime`>1363427100 AND `dateTime`<1363431300 THEN 11 WHEN `dateTime`>1363431300 AND `dateTime`<1363435500 THEN 12 WHEN `dateTime`>1364238300 AND `dateTime`<1364242200 THEN 13 WHEN `dateTime`>1364694900 AND `dateTime`<1364698800 THEN 14 WHEN `dateTime`>136721